// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0x0));
            vm.assume(tos[i] != address(c));
        }
        bytes4 selector = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(contract_address != tos[i]);
        }
        // deploy a helper that succeeds on the external calls to avoid revert
        Successor successor = new Successor();
        // ensure the fuzzed contract_address is the successor to make calls succeed
        contract_address = address(successor);
        bool result = c.transfer(contract_address, tos, vs);
        assertTrue(result);
    }
}

contract Successor {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
